Το παρακάτω συμβόλαιο επιτρέπει σε έναν ιδιοκτήτη να πουλά ένα πατίνι και σε έναν αγοραστή να το αγοράζει. Ο ιδιοκτήτης ορίζει την τιμή και ο αγοραστής καταβάλλει το αντίτιμο σε ether. Αν η συναλλαγή ολοκληρωθεί επιτυχώς, το πατίνι μεταβιβάζεται και το αντίτιμο δεσμεύεται σε λογαριασμό του αγοραστή.

```solidity
// SPDX-License-Identifier: MIT

contract ElectricScooter {
    address public owner;
    address public buyer;
    uint256 public price;
    bool public sold;

    event ScooterSold(address indexed buyer, uint256 indexed price);

    constructor(uint256 _price) {
        owner = msg.sender;
        price = _price;
    }

    function sellScooter() public payable {
        require(!sold, "Scooter already sold");
        require(msg.value >= price, "Insufficient payment");
        buyer = msg.sender;
        sold = true;
        emit ScooterSold(buyer, price);
    }

    function transferOwnership(address newOwner) public {
        require(msg.sender == owner, "Unauthorized");
        owner = newOwner;
    }

    function getPrice() public view returns (uint256) {
        return price;
    }

    function getBuyer() public view returns (address) {
        return buyer;
    }

    function getSold() public view returns (bool) {
        return sold;
    }
}
```

Το συμβόλαιο ορίζει τον ιδιοκτήτη, την τιμή, τον αγοραστή και την κατάσταση πώλησης. Ο ιδιοκτήτης μπορεί να μεταβιβάσει την κυριότητα, ενώ ο αγοραστής μπορεί να πουλήσει το πατίνι μόνο μία φορά. Η τιμή δηλώνεται κατά τη δημιουργία του συμβολαίου και ο αγοραστής πρέπει να καταβάλει τουλάχιστον το αντίστοιχο ether. Η μεταβίβαση ενεργοποιείται μόνο όταν ολοκληρωθεί επιτυχώς η πληρωμή.

