def max_product(lst):
    if len(lst) < 2:
        return None
    max1 = max2 = float('-inf')
    for num in lst:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num
        max1 = max(max1, num)
    return max(max1, max2)

